changes.release/changelog-writer/scripts/reach.p:
"""Which rules reach one skill run, the jobs that group skills, and the one size count.

Standard library only. This is the one rule of the agreed size design (reviews/release-design/size-final.md,
section 1): a rule reaches a run when, and only when,
  1. it is a floor whose Applies to names one of the run's roles;
  2. its Applies to says "every role";
  3. it is a decision point whose Applies to names one of the run's roles;
  4. it names one of the run's roles and its area is in the skill's areas;
  5. a step of the skill cites it;
  6. it overrides, binds or tightens a rule that reaches the run, applied repeatedly.
Only active rules reach (docs/design/03-standards.md, resolver input 1). Jobs and the `rest` skill follow section 2
of the same design and v2/roles.md. Every failure raises ReachError naming what is wrong.
"""

import re
from dataclasses import dataclass

from rulebook import EVERY_ROLE, NAME, ROLE, RulebookError, split_list

REST = "rest"
CEILING = 30000  # characters: floors, rest and a rules text each stay at or under it (check_release.py keeps its own)
AREA = re.compile(NAME)


class ReachError(RulebookError):
    """A skill, job or citation that the one rule cannot place."""


@dataclass(frozen=True)
class Skill:
    name: str
    roles: tuple
    areas: tuple  # area names, or ("rest",)

    @property
    def is_rest(self):
        return self.areas == (REST,)


def size(text):
    """The one count for all three ceilings: Unicode code points."""
    return len(text)


def read_skill(name, frontmatter):
    """A Skill from a template's frontmatter, as rulebook.read_frontmatter returns it."""
    metadata = frontmatter.get("metadata", {})
    roles, areas = split_list(metadata.get("roles", "")), split_list(metadata.get("areas", ""))
    if frontmatter.get("name") != name:
        raise ReachError(f"{name}: frontmatter name is {frontmatter.get('name')!r}, not the folder name")
    if not roles or len(set(roles)) != len(roles) or not all(ROLE.fullmatch(r) and r != EVERY_ROLE for r in roles):
        raise ReachError(f"{name}: metadata.roles must list distinct role names: {metadata.get('roles')!r}")
    rest = areas == [REST]
    if not rest and (not areas or len(set(areas)) != len(areas) or not all(AREA.fullmatch(a) for a in areas)):
        raise ReachError(f"{name}: metadata.areas must be `rest` or distinct area names: {metadata.get('areas')!r}")
    return Skill(name, tuple(roles), tuple(areas))


def check_jobs(jobs, skills):
    """Map each skill name to its job row. jobs is read_roles()["jobs"]; skills maps name -> Skill.

    Fails a job naming an unknown skill, a skill in two jobs or in none, a skill whose roles differ from its job's,
    and a job without exactly one `rest` skill, the one its row names. No jobs and no skills passes.
    """
    owner = {}
    for job_name, row in jobs.items():
        for skill_name in row["Skills in order"]:
            if skill_name not in skills:
                raise ReachError(f"job {job_name} names {skill_name}, which has no template")
            if skill_name in owner:
                raise ReachError(f"{skill_name} is in two jobs: {owner[skill_name]['Job']} and {job_name}")
            if set(skills[skill_name].roles) != set(row["Roles"]):
                raise ReachError(f"{skill_name}: metadata.roles {', '.join(skills[skill_name].roles)} differ from "
                                 f"job {job_name}'s roles {', '.join(row['Roles'])}")
            owner[skill_name] = row
        rest = [s for s in row["Skills in order"] if skills[s].is_rest]
        if rest != [row["`rest` skill"]]:
            raise ReachError(f"job {job_name} needs exactly one `rest` skill, {row['`rest` skill']}; "
                             f"its templates mark {', '.join(rest) or 'none'}")
    for skill_name in skills:
        if skill_name not in owner:
            raise ReachError(f"{skill_name} is in no job")
    return owner


def job(jobs, name):
    """The job row a pipeline step names. Fails an unknown job."""
    if name not in jobs:
        raise ReachError(f"unknown job {name!r}; the roles file lists {', '.join(sorted(jobs)) or 'no jobs'}")
    return jobs[name]


def areas_of(skill, row, skills, rules):
    """The skill's areas. For the `rest` skill: every area of a rule naming one of the job's roles that no other
    skill of the job lists. Decision points have no area here; they reach by item 3."""
    if not skill.is_rest:
        return set(skill.areas)
    listed = {a for s in row["Skills in order"] for a in skills[s].areas}  # `rest` itself is no area
    named = {r.area for r in active(rules) if not r.is_decision_point and set(r.applies_to) & set(row["Roles"])}
    return named - listed


def active(rules):
    return [r for r in rules if r.status == "active"]


@dataclass
class Reach:
    floors: list  # floors, in rulebook order
    others: list  # every other rule that reaches, decision points included, in rulebook order
    cited_points: set  # IDs of decision points a step cites, which get their full copy form

    @property
    def rules(self):
        return self.floors + self.others


def reach(rules, roles, areas, cited, replaces=None):
    """The rules that reach a run of a skill with these roles and areas whose steps cite these IDs.

    rules are in rulebook order, from every layer the caller reads. A cited ID that is not an active rule fails.
    replaces maps a rule ID to the IDs a resolve found it replaces, which item 6 follows too: an override that names
    a CORE rule replaces the language rule standing in its place.
    """
    live = active(rules)
    by_id = {r.id: r for r in live}
    for rule_id in cited:
        if rule_id not in by_id:
            known = any(r.id == rule_id for r in rules)
            raise ReachError(f"cited {rule_id} is {'not active' if known else 'not in the rulebook'}")
    roles = set(roles)
    reached = set(cited)
    for rule in live:
        names = set(rule.applies_to)
        if EVERY_ROLE in names or (names & roles and (
                rule.kind in ("floor", "decision point") or rule.area in areas)):
            reached.add(rule.id)
    grew = True
    while grew:
        changers = {r.id for r in live if r.id not in reached and (
            r.changes in reached or set((replaces or {}).get(r.id, ())) & reached)}
        reached |= changers
        grew = bool(changers)
    kept = [r for r in live if r.id in reached]
    points = {i for i in cited if by_id[i].is_decision_point}
    return Reach([r for r in kept if r.kind == "floor"], [r for r in kept if r.kind != "floor"], points)

changes.release/changelog-writer/scripts/repopro:
"""The team settings reader for resolve.py: .harness/profile.yaml and a layer's layer.yaml (plan/b01-plan.md part e).

Standard library only. Shipped in each release skill's scripts/ beside resolve.py, and imports only rulebook.py. One
rule governs it: every value is a node that carries its own line, every line of a read section is used, and
anything else stops the run naming the file and line (HW-AG-09). The forms it reads are stated in
docs/design/07-repo-profile.md "Format".
"""

import re
from dataclasses import dataclass

import reach
import rulebook
from rulebook import DP_ID, RULE_ID, RulebookError, fail

PROFILE = ".harness/profile.yaml"
MAX_LIMIT = 60000
DEFAULT_LIMIT = reach.CEILING
READ = ("harnesswright", "standards", "waivers", "rules-text-limit", "decisions")
SKIP = ("toolchain", "scripts", "models", "capabilities", "process")  # doc 07's sections that resolve does not read
VALUE = re.compile(f"{rulebook.PRINTABLE}+")
ACCOUNT = r"[A-Za-z0-9._-]+"
SHAPES = {
    "version": re.compile(r"[0-9]+\.[0-9]+\.[0-9]+"),
    "folder": re.compile(r"[A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+)*/?"),
    "name": re.compile(r"[a-z][a-z0-9]*"),
    "language": re.compile(r"[a-z][a-z0-9]*(?:-[a-z][a-z0-9]*)*"),
    "rule": re.compile(rf"{RULE_ID.pattern}|{DP_ID.pattern}"),
    "until": rulebook.DATE,
    "reason": VALUE,
    "approved by": re.compile(rf"{ACCOUNT}(?:, ?{ACCOUNT})*"),
    "owner": VALUE,
    "limit": re.compile(r"[1-9][0-9]*"),
    "key": re.compile(r"[a-z0-9]+(?:-[a-z0-9]+)*"),
    "option": re.compile(r"[a-z0-9-]+"),
}
LINE = re.compile(r"( *)(- )?(?:([a-z][a-z0-9 -]*[a-z0-9]|[a-z]):(?: +(.*))?|(.+))")  # key: value, or - item
COMMENT = re.compile(r"(?:^|\s)#")
QUOTED_END = re.compile(r"\s*|\s+#.*")
# An unquoted value: no YAML indicator first, no `: ` inside, and not a word YAML reads as true, false or null.
PLAIN = re.compile(rf"(?!{rulebook.WORDS}$)[A-Za-z0-9._/](?:(?!: ){rulebook.PRINTABLE})*")


class ResolveError(RulebookError):
    """An input that stops the run, named with its file and line or its layer."""


@dataclass
class Node:
    """One parsed value and the line it starts on: text, a list of Nodes, or a dict of key to Node."""
    line: int
    value: object


def read_file(path, label=""):
    """The file's lines; a file that is missing or cannot be read stops the run naming it."""
    try:
        return rulebook.read_lines(path)
    except (OSError, UnicodeDecodeError) as error:
        raise ResolveError(f"{label}{path}: is missing or cannot be read ({type(error).__name__})") from None


def scalar(path, number, raw):
    """A value's text: quoted text in full, or the text before a ` #` comment. `[]`, `{}` and `[a, b]` give a list
    or dict. None when the line has no value."""
    if raw and raw[0] in "\"'":
        end = raw.find(raw[0], 1)
        if end < 0 or not QUOTED_END.fullmatch(raw[end + 1:]):
            fail(path, number, "a quoted value must end with its quote, then nothing or a comment")
        if raw[0] == '"' and "\\" in raw[1:end]:
            fail(path, number, "a quoted value has no escapes such as \\u0020; write the character itself")
        return raw[1:end]
    text = COMMENT.split(raw or "", maxsplit=1)[0].rstrip()
    if text in ("", "[]", "{}"):
        return {"": None, "[]": [], "{}": {}}[text]
    if text[0] == "[" and text[-1] == "]":
        parts = [part.strip() for part in text[1:-1].split(",")]
        if not all(parts):
            fail(path, number, f"a list written as [a, b] has an empty item: {text!r}")
        return [Node(number, scalar(path, number, part)) for part in parts]
    if not PLAIN.fullmatch(text):
        fail(path, number, f"{text!r} must be quoted: an unquoted value starts with a letter, digit, `.`, `_` or `/`, "
                           "holds no `: ` and is not a word such as yes, no, true, false or null")
    return text


def token(path, number, line):
    """[number, indent, dash, key, value] of one line, or a stop naming it."""
    found = LINE.fullmatch(line)
    if not found or (found.group(5) is not None and not found.group(2)):
        fail(path, number, f"line has no allowed shape here: {line!r}")
    indent, dash, key, raw, item = found.groups()
    value = scalar(path, number, raw if key else item)
    if key is None and value is None:
        fail(path, number, "a list item has no value")
    return [number, len(indent), bool(dash), key, value]


def parse(path, tokens, start, indent):
    """The block that starts at tokens[start], every line at this indent: a dict of key to Node, or a list of
    Nodes for `- ` items. Returns it with the index after it. Every line is used, or the run stops naming it."""
    as_list = tokens[start][2]
    block, index = ([] if as_list else {}), start
    while index < len(tokens) and tokens[index][1] >= indent:
        number, here, dash, key, value = tokens[index]
        if here != indent:
            fail(path, number, "line is not indented like the other lines of its block")
        if dash != as_list:
            fail(path, number, "a block mixes list items and keys")
        if as_list and key is not None:  # a `- key: value` item: a block of keys that starts after the dash
            tokens[index] = [number, indent + 2, False, key, value]
            item, index = parse(path, tokens, index, indent + 2)
            block.append(Node(number, item))
            continue
        index += 1
        if as_list:
            block.append(Node(number, value))
            continue
        if key in block:
            fail(path, number, f"{key!r} appears twice")
        if value is None:
            if index == len(tokens) or tokens[index][1] <= indent:
                fail(path, number, f"{key!r} has no value")
            value, index = parse(path, tokens, index, tokens[index][1])
        block[key] = Node(number, value)
    return block, index


def read_yaml(path, read, skip=(), label=""):
    """The file's top-level sections as a Node of key to Node. A section in read is parsed in full; a section in
    skip is passed over unread; any other section stops the run."""
    lines = [(n, line) for n, line in enumerate(read_file(path, label), 1)
             if line.strip() and not line.lstrip(" ").startswith("#")]
    if lines and lines[0][1] == "---":
        lines = lines[1:]
    tops = [i for i, (_, line) in enumerate(lines) if not line.startswith(" ")] + [len(lines)]
    if lines and tops[0] != 0:
        fail(path, lines[0][0], "an indented line comes before the first section")
    data = {}
    heads = []
    for here in tops[:-1]:  # every top-level line first, so a stray one stops at its own line
        number, line = lines[here]
        heads.append(token(path, number, line))
        if heads[-1][2] or heads[-1][3] is None:
            fail(path, number, f"a top-level line must be `section:`; indent list items under their key: {line!r}")
    for head, here, after in zip(heads, tops, tops[1:]):
        number = head[0]
        if head[3] in data:
            fail(path, number, f"{head[3]!r} appears twice")
        if head[3] in skip:
            data[head[3]] = None
            continue
        if head[3] not in read:
            fail(path, number, f"{head[3]!r} is not a section; allowed: {', '.join(read + skip)}")
        tokens = [head] + [token(path, n, text) for n, text in lines[here + 1:after]]
        data.update(parse(path, tokens, 0, 0)[0])
    return Node(1, {k: v for k, v in data.items() if v is not None})


def leaf(path, node, shape):
    """One value: text with the named shape, for `until` also a real date."""
    if not isinstance(node.value, str):
        fail(path, node.line, f"expected one {shape} value")
    if not SHAPES[shape].fullmatch(node.value) or (shape == "until" and not rulebook.is_date(node.value)):
        fail(path, node.line, f"{node.value!r} is not an allowed {shape}")
    return node.value


def keys(path, node, required, optional=()):
    """A dict holding every required key and no key outside required and optional."""
    allowed = ", ".join([*required, *optional]) or "none"
    if not isinstance(node.value, dict):
        fail(path, node.line, f"expected keys: {allowed}")
    for key, child in node.value.items():
        if key not in (*required, *optional):
            fail(path, child.line, f"{key!r} is not allowed here; allowed: {allowed}")
    missing = [k for k in required if k not in node.value]
    if missing:
        fail(path, node.line, f"missing {', '.join(missing)}")
    return node.value


def items(path, node, what):
    if not isinstance(node.value, list):
        fail(path, node.line, f"expected a list of {what}")
    return node.value


def read_profile(path):
    """The sections of .harness/profile.yaml that resolve reads, checked against their allowed shapes."""
    data = keys(path, read_yaml(path, READ, SKIP), ["harnesswright"], READ[1:])
    install = keys(path, data["harnesswright"], ["version", "folder"])
    profile = {"version": leaf(path, install["version"], "version"), "folder": leaf(path, install["folder"], "folder"),
               "languages": [], "language lines": [], "layers": [], "repository": None, "waivers": [],
               "limit": DEFAULT_LIMIT, "decisions": {}}
    standards = keys(path, data.get("standards", Node(1, {})), [], ["languages", "layers", "repository"])
    for node in items(path, standards.get("languages", Node(1, [])), "language names"):
        profile["languages"].append(leaf(path, node, "language"))
        profile["language lines"].append(node.line)
    for node in items(path, standards.get("layers", Node(1, [])), "layers"):
        layer = keys(path, node, ["name", "folder", "version"])
        profile["layers"].append({**{k: leaf(path, layer[k], k) for k in ("name", "folder", "version")},
                                  "line": node.line})
    if "repository" in standards:
        profile["repository"] = leaf(path, standards["repository"], "folder")
    seen = {}
    for node in items(path, data.get("waivers", Node(1, [])), "waivers"):
        waiver = {k: leaf(path, v, k) for k, v in keys(path, node, ["rule", "reason", "until", "approved by"]).items()}
        if waiver["rule"] in seen:
            fail(path, node.line, f"{waiver['rule']} already has a waiver on line {seen[waiver['rule']]}")
        seen[waiver["rule"]] = node.line
        profile["waivers"].append({**waiver, "line": node.line})
    if "rules-text-limit" in data:
        node = data["rules-text-limit"]
        profile["limit"] = int(leaf(path, node, "limit"))
        if profile["limit"] > MAX_LIMIT:
            fail(path, node.line, f"rules-text-limit {profile['limit']} is over the maximum of {MAX_LIMIT}")
    decisions = data.get("decisions", Node(1, {}))
    if not isinstance(decisions.value, dict):
        fail(path, decisions.line, "expected one `point: option` line for each decision point")
    for key, node in decisions.value.items():
        profile["decisions"][leaf(path, Node(node.line, key), "key")] = (leaf(path, node, "option"), node.line)
    return profile


def read_layer_yaml(name, folder, version, files):
    """The owner of a layer 3 to 5 folder, after checking its layer.yaml and its version against the profile."""
    path = folder / "layer.yaml"
    files.append(path)
    data = keys(path, read_yaml(path, ("owner", "version"), label=f"layer {name}: "), ["owner", "version"])
    found = leaf(path, data["version"], "version")
    if found != version:
        raise ResolveError(f"layer {name} ({folder}): version {found} is not the profile's {version}")
    return leaf(path, data["owner"], "owner")

changes.release/changelog-writer/scripts/resolve:
"""The standards reader's command: resolve an application's rule layers (plan/b01-plan.md part e).

Standard library only. Shipped in each release skill's scripts/ beside rulebook.py, reach.py, copyform.py,
repoprofile.py and runfiles.py, and imports only them. It reads the team settings with repoprofile.py, then every
layer the run uses, and stops on any break of docs/design/03-standards.md "Resolving the rules for an application"
and docs/design/07-repo-profile.md, naming the file and line or the layer and folder (HW-AG-09). Part e1a reads and
checks these inputs; parts e1b and e2 combine them, and runfiles.py writes rules.md and the rules texts.

Run: python3 resolve.py --repo REPO --run RUN-ID --date YYYY-MM-DD
"""

import argparse
import json
import re
import sys
from dataclasses import dataclass, field
from datetime import date
from pathlib import Path

import reach
import rulebook
import runfiles
from repoprofile import PROFILE, RulebookError, ResolveError, read_layer_yaml, read_profile
from rulebook import DP_ID, EVERY_ROLE, fail

LEVELS = ("COMP", "DEPT", "TEAM")  # company, department, team: layers 3 to 5, most general first
RUN_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*")
# A change relation is allowed only between these kinds (plan/b01-plan.md "Change relations").
WAIVABLE = ("principle", "idiom", "choice")
RELATIONS = {"Tightens": ({"floor"}, {"floor"}), "Binds": ({"choice"}, {"decision point"}),
             "Overrides": ({"principle", "idiom", "choice"}, {"principle", "idiom", "choice"})}


@dataclass
class Source:
    """One layer the run reads, most general first."""
    prefix: str  # the ID prefix its rules carry: CORE, JAVA-SPRING, COMP-ACME, APP
    folder: Path
    owner: str
    rules: dict = field(default_factory=dict)  # ID -> rulebook.Rule


@dataclass
class Inputs:
    version: str
    release: Path
    sources: list  # Source, most general first
    roles: set
    decisions: dict  # decision point ID -> (option, profile line)
    waivers: list  # dicts with rule, reason, until, approved by, line; not expired
    expired: list  # the same, `until` before the run date
    limit: int
    files: list = field(default_factory=list)  # every file read, in reading order
    manifest: dict = field(default_factory=dict)  # the release manifest: its version and each skill's entry
    jobs: dict = field(default_factory=dict)  # the release roles file's Jobs table



def prefix_of(rule_id):
    """The layer prefix of an ID: CORE for CORE-TEST-03 and CORE-DP-STACK, JAVA-SPRING for JAVA-SPRING-WEB-01."""
    return rule_id.split("-DP-")[0] if DP_ID.fullmatch(rule_id) else "-".join(rule_id.split("-")[:-2])


def add_source(sources, name, prefixes, folder, owner, files):
    """Read one layer folder and add it to sources. Every layer passes through here: its folder and files must be
    readable, it holds at least one rule, every rule carries one of prefixes, and no other layer has its prefix."""
    paths = sorted(p for p in folder.glob("*.md") if p.name not in rulebook.NOT_RULE_FILES) if folder.is_dir() else []
    for path in paths:
        try:
            path.read_bytes().decode("utf-8")
        except (OSError, UnicodeDecodeError) as error:
            raise ResolveError(f"layer {name} ({folder}): {path} cannot be read ({type(error).__name__})") from None
    if not paths:
        raise ResolveError(f"layer {name}: folder {folder} is missing, cannot be read or holds no rule file")
    rules = rulebook.read_layer(folder).rules
    files += paths
    found = {prefix_of(rule_id) for rule_id in rules}
    if len(found) != 1 or not found <= set(prefixes):
        raise ResolveError(f"layer {name} ({folder}): its rule IDs carry {sorted(found) or 'no rule'}; "
                           f"they must all carry one of {', '.join(prefixes)}")
    prefix = found.pop()
    other = next((s for s in sources if s.prefix == prefix), None)
    if other:
        raise ResolveError(f"layer {name} ({folder}) carries {prefix}, which {other.folder} already holds; "
                           "each layer is listed once")
    sources.append(Source(prefix, folder, owner, rules))
    return sources[-1]


ENTRY = {"job": str, "rest": bool, "roles": list, "areas": list, "copied-ids": list}  # what resolve reads of a skill


def read_manifest(path):
    """The release manifest: its version, and per skill the entry keys resolve reads, each of its shape."""
    try:
        manifest = json.loads(Path(path).read_text(encoding="utf-8"))
        ok = isinstance(manifest["rulebook-version"], str) and isinstance(manifest["skills"], dict) and all(
            isinstance(e, dict) and all(isinstance(e.get(k), t) for k, t in ENTRY.items())
            for e in manifest["skills"].values())
    except (OSError, UnicodeDecodeError, ValueError, TypeError, KeyError):
        ok = False
    if not ok:
        raise ResolveError(f"release: {path} is missing or cannot be read as a release manifest")
    return manifest


def load(repo, today):
    """Read and check every input of a run; any break of the plan's stops raises ResolveError."""
    repo = Path(repo)
    path = repo / PROFILE
    profile, files = read_profile(path), [path]
    release = repo / profile["folder"]
    manifest_path = release / "manifest.json"
    manifest = read_manifest(manifest_path)
    files += [manifest_path, release / "roles.md"]
    if manifest["rulebook-version"] != profile["version"]:
        raise ResolveError(f"release ({release}): version {manifest['rulebook-version']} is not the profile's "
                           f"{profile['version']}")
    try:
        table = rulebook.read_roles(release / "roles.md")
    except (OSError, UnicodeDecodeError):
        raise ResolveError(f"release: {release / 'roles.md'} is missing or cannot be read") from None
    roles = set(table["roles"])
    for job in sorted(set(table["jobs"]) | {e["job"] for e in manifest["skills"].values()}):
        listed = table["jobs"].get(job, {}).get("Skills in order", [])
        named = sorted(n for n, e in manifest["skills"].items() if e["job"] == job)
        if sorted(listed) != named:  # one list of a job's skills, so each skill's job and `rest` areas are known
            raise ResolveError(f"release: job {job} lists skills {listed} in roles.md, but {manifest_path} gives "
                               f"it {named}")
    sources = []
    add_source(sources, "CORE", ("CORE",), release / "rules" / "core", "harnesswright", files)
    for index, (language, number) in enumerate(zip(profile["languages"], profile["language lines"])):
        base = language.split("-")[0]  # a framework `x-y` belongs to the language `x`
        if base != language and base not in profile["languages"][:index]:
            fail(path, number, f"standards.languages lists framework {language} without its language {base} before it")
        add_source(sources, language, (language.upper(),), release / "rules" / language, "harnesswright", files)
    level = -1
    for layer in profile["layers"]:
        folder = repo / layer["folder"]
        owner = read_layer_yaml(layer["name"], folder, layer["version"], files)
        prefixes = tuple(f"{lvl}-{layer['name'].upper()}" for lvl in LEVELS)
        here = LEVELS.index(add_source(sources, layer["name"], prefixes, folder, owner, files).prefix.split("-")[0])
        if here <= level:
            fail(path, layer["line"], f"layer {layer['name']} ({folder}) is a {LEVELS[here]} layer listed after a "
                 f"{LEVELS[level]} layer; list at most one company, then department, then team layer")
        level = here
    if profile["repository"]:
        add_source(sources, "application", ("APP",), repo / profile["repository"], "the application owner", files)
    check_rules(sources, roles)
    inputs = Inputs(profile["version"], release, sources, roles, check_decisions(path, profile, sources), [], [],
                    profile["limit"], files, manifest, table["jobs"])
    check_waivers(path, profile, sources, today, inputs)
    return inputs


def language_of(source):
    """The language a language or framework layer belongs to (JAVA for JAVA-SPRING), or None for any other layer.
    It takes a Source or a layer prefix."""
    prefix = getattr(source, "prefix", source)
    base = prefix.split("-")[0]
    return None if prefix == "APP" or base in ("CORE",) + LEVELS else base


def builds_on(source, prefix):
    """A language or framework layer builds on CORE and its own language only; any other layer builds on every more
    general layer. No two languages are ranked, so neither may change the other's rules."""
    return language_of(source) is None or prefix == "CORE" or language_of(prefix) == language_of(source)


def stacks(sources):
    """One stack per language, resolved on its own: CORE, the language and its frameworks, then layers 3 to 6. An
    application with no language has one stack, named core."""
    languages = list(dict.fromkeys(language_of(s) for s in sources if language_of(s)))
    return [(name.lower(), [s for s in sources if language_of(s) in (None, name)]) for name in languages or ["CORE"]]


def active(source):
    return [r for r in source.rules.values() if r.status == "active"]


def check_rules(sources, roles):
    """Applies to names known roles; each change relation is allowed and reaches a more general layer. No ID can be
    in two layers: each layer has its own prefix (add_source)."""
    for index, source in enumerate(sources):
        for rule in active(source):
            where = f"{rule.file}:{rule.line}: {rule.id}"
            unknown = [n for n in rule.applies_to if n != EVERY_ROLE and n not in roles]
            if index and unknown:
                raise ResolveError(f"{where}: Applies to names roles not in the release's roles.md: {unknown}")
            relation = next((name for name in rulebook.CHANGES if name in rule.parts), None)
            if relation is None:
                continue
            target = next((s.rules[rule.changes] for s in sources[:index] if rule.changes in s.rules), None)
            if target is None or target.status != "active":
                raise ResolveError(f"{where}: {relation} {rule.changes}, which no more general layer holds active")
            if not builds_on(source, prefix_of(target.id)):
                raise ResolveError(f"{where}: {relation} {target.id}, a rule of another language; a language "
                                   "changes only CORE rules and its own language's")
            kinds, target_kinds = RELATIONS[relation]
            if rule.kind not in kinds or target.kind not in target_kinds:
                raise ResolveError(f"{where}: {relation} may not go from a {rule.kind} to a {target.kind}; it goes "
                                   f"from {'/'.join(sorted(kinds))} to {'/'.join(sorted(target_kinds))}")
            if relation == "Overrides" and "Binds" in target.parts:
                raise ResolveError(f"{where}: Overrides {target.id}, a binding; a binding changes only by binding "
                                   "its point again")
            if relation == "Binds" and rule.option not in target.options:
                raise ResolveError(f"{where}: option {rule.option!r} is not one of {target.id}'s Options")


def check_decisions(path, profile, sources):
    """Each profile decision names one active decision point in each stack that holds one, at least one in all, and
    one of each named point's Options. So `boilerplate` binds JAVA-DP-BOILERPLATE and KOTLIN-DP-BOILERPLATE alike."""
    bound = {}
    for key, (option, number) in profile["decisions"].items():
        named = {}
        for _, stack in stacks(sources):
            here = [r for s in stack for r in active(s) if r.is_decision_point and r.id.endswith("-DP-" + key.upper())]
            if len(here) > 1:
                fail(path, number, f"decisions key {key!r} names {len(here)} active decision points in one stack "
                                   f"({', '.join(r.id for r in here)}); it must name one")
            named.update({r.id: r for r in here})
        if not named:
            fail(path, number, f"decisions key {key!r} names 0 active decision points; it must name one")
        for point in named.values():
            if option not in point.options:
                fail(path, number, f"option {option!r} is not one of {point.id}'s Options")
            bound[point.id] = (option, number)
    return bound


def check_waivers(path, profile, sources, today, inputs):
    """Each waiver names an active principle, idiom or choice that binds no decision point; one whose `until` has
    passed is set aside. A floor is never waived (HW-RULE-06); a binding changes only by binding the point again."""
    rules = {r.id: r for s in sources for r in active(s)}
    for waiver in profile["waivers"]:
        rule = rules.get(waiver["rule"])
        if rule is None:
            fail(path, waiver["line"], f"waiver of {waiver['rule']}, which no layer holds active")
        if rule.kind not in WAIVABLE or "Binds" in rule.parts:
            fail(path, waiver["line"], f"waiver of {rule.id}, a {'binding' if 'Binds' in rule.parts else rule.kind}"
                                       "; only a principle, idiom or choice that binds no decision point is waived "
                                       "(a floor never is, HW-RULE-06; bind a point again in decisions)")
        expired = date.fromisoformat(waiver["until"]) < today
        (inputs.expired if expired else inputs.waivers).append(waiver)


@dataclass
class Resolved:
    """Doc 03 steps 1 to 4 for one stack: the rules that apply, in layer order, and what each point resolves to."""
    stack: str
    rules: dict = field(default_factory=dict)  # ID -> (rule, layer prefix, change text), most general first
    replaced: dict = field(default_factory=dict)  # ID of a rule that no longer applies -> the ID that replaced it
    points: dict = field(default_factory=dict)  # decision point ID -> (option, where it comes from)
    waivers: list = field(default_factory=list)  # the waivers and expired waivers of rules in this stack

    def last(self, rule_id):
        """The rule that replaces rule_id in the end, following a chain of replacements."""
        while rule_id in self.replaced:
            rule_id = self.replaced[rule_id]
        return rule_id


def combine(inputs):
    """Resolve each stack (one per language) on its own."""
    return [combine_stack(inputs, name, sources) for name, sources in stacks(inputs.sources)]


def combine_stack(inputs, name, sources):
    """Apply each layer most general first, then the profile's bindings, then the defaults, then the waivers.
    One rule: a rule that loses to a more specific input (an override, or a later binding of its point) leaves the
    rules and is recorded in `replaced`, and a change relation must name a rule that still applies. A rule that
    changes a rule of another stack's language belongs to that stack only."""
    done, bound, app_binds = Resolved(name), {}, {}  # bound: decision point ID -> the binding rule that applies now

    def replace(old, new):
        del done.rules[old]
        done.replaced[old] = new

    for source in sources:
        binds = {}  # decision point ID -> the rule in this layer that binds it
        for rule in active(source):
            relation = next((name for name in rulebook.CHANGES if name in rule.parts), None)
            change = f"{relation} {rule.changes}" if relation else ""
            change += f": {rule.option}" if relation == "Binds" else ""
            if relation and rule.changes not in done.rules and rule.changes not in done.replaced:
                continue  # it changes another language's rule, so it belongs to that language's stack only
            target = rule.changes
            if relation and prefix_of(target) == "CORE" and not language_of(source) and source.prefix != "CORE":
                while target in done.replaced and language_of(prefix_of(done.replaced[target])):
                    target = done.replaced[target]  # a language's replacement stands in the principles rule's place
            if relation and target in done.replaced:
                by = done.replaced[target]
                advice = ("its layer's owner keeps one of the two" if prefix_of(by) == source.prefix else
                          "name that rule instead")
                raise ResolveError(f"{rule.file}:{rule.line}: {rule.id} {relation} {target}, which {by} "
                                   f"already replaces; {advice}")
            if relation == "Overrides":
                replace(target, rule.id)
            if relation == "Binds":
                if rule.changes in binds:
                    raise ResolveError(f"{rule.file}:{rule.line}: {rule.id} binds {rule.changes}, which "
                                       f"{binds[rule.changes].id} already binds in layer {source.prefix}")
                if rule.changes in bound:
                    replace(bound[rule.changes].id, rule.id)
                binds[rule.changes] = bound[rule.changes] = rule
            done.rules[rule.id] = (rule, source.prefix, change)
        app_binds = binds if source.prefix == "APP" else app_binds
    decisions = {point: value for point, value in inputs.decisions.items() if point in done.rules}
    for point, (option, number) in decisions.items():
        if point in app_binds:
            fail(inputs.files[0], number, f"{point} is bound twice in the application layer: here and by "
                                          f"{app_binds[point].id}")
        if point in bound:
            replace(bound[point].id, "profile decisions")
    done.points = {point: (rule.option, rule.id) for point, rule in bound.items()}
    done.points.update({point: (option, "profile decisions") for point, (option, _) in decisions.items()})
    for rule, _, _ in done.rules.values():
        if rule.is_decision_point and rule.id not in done.points:
            done.points[rule.id] = (rule.default, "default")
    done.waivers = [w for w in inputs.waivers + inputs.expired if w["rule"] in done.rules or w["rule"] in done.replaced]
    return done


def run_files(repo, run, today, inputs):
    """What the run writes: rules.md, one rules text per skill and stack (path -> text), and the rules texts parked
    over the ceiling ((skill, stack) -> size, owner of its largest layer, sizes per layer and area)."""
    stacks_done = combine(inputs)
    held = [[r for s in sources for r in active(s) if r.id in done.rules or r.id in done.replaced]  # a rule that
            for (_, sources), done in zip(stacks(inputs.sources), stacks_done)]  # changes another stack's is not here
    texts, parked = {}, {}
    for name in sorted(inputs.manifest["skills"]):
        for rules, done in zip(held, stacks_done):
            text, full = runfiles.rules_text(name, inputs, rules, done)
            if reach.size(text) > inputs.limit:
                parked[(name, done.stack)] = (reach.size(text), *runfiles.largest_owner(full, inputs))
            else:
                texts[Path(repo) / runfiles.RULES_TEXT.format(run=run, skill=name, stack=done.stack)] = text
    summary = {key: (size, owner) for key, (size, owner, _) in parked.items()}
    return runfiles.rules_md(repo, run, today, inputs, stacks_done, texts, summary), texts, parked


def main(argv=None):
    """Exit 0 when every rules text is written, 3 when one is parked over the ceiling, 1 when the run stops."""
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--repo", required=True)
    parser.add_argument("--run", required=True)
    parser.add_argument("--date", required=True, type=date.fromisoformat)
    args = parser.parse_args(argv)
    try:
        if not RUN_ID.fullmatch(args.run):
            raise ResolveError(f"run id {args.run!r} must be letters, digits, '.', '_' or '-'")
        inputs = load(args.repo, args.date)
        text, texts, parked = run_files(args.repo, args.run, args.date, inputs)
        path = runfiles.write_once(Path(args.repo) / runfiles.RULES_MD.format(run=args.run), text)
        for rules_text_path, rules_text in texts.items():
            runfiles.write_once(rules_text_path, rules_text)
    except RulebookError as error:
        print(f"resolve stopped: {error}", file=sys.stderr)
        return 1
    print(f"resolve: wrote {path} and {len(texts)} rules texts", file=sys.stderr)
    for (name, stack), (size, owner, sizes) in parked.items():
        print(f"resolve: parked {name} ({stack}): its rules text is {size} characters, over the limit of "
              f"{inputs.limit}; it goes to {owner}. Sizes per layer and area:", file=sys.stderr)
        for (layer, area), count in sorted(sizes.items()):
            print(f"  {layer} {area}: {count}", file=sys.stderr)
    return 3 if parked else 0


if __name__ == "__main__":
    sys.exit(main())

changes.release/changelog-writer/scripts/ruleboo:
"""Read a rulebook layer folder, the roles file and skill frontmatter into plain data.

Standard library only. One rule governs the whole module: every line, and every value inside a line, must match a
shape listed here (HW-AG-09). Anything else raises RulebookError naming the file and line, so nothing is skipped or
guessed. The formats are those of docs/design/03-standards.md (rule parts, IDs, retired rules), v2/rules/README.md
(Review by) and v2/roles.md (roles and jobs tables).
"""

import re
from datetime import date
from dataclasses import dataclass, field
from pathlib import Path

EVERY_ROLE = "every role"
KINDS = ("principle", "floor", "idiom", "choice")
STATUSES = ("active", "inferred", "retired")
CLASSES = ("deep", "standard", "fast")
CHANGES = ("Overrides", "Binds", "Tightens")
RULE_REQUIRED = ("Kind", "Status", "Review by", "Applies to", "Rule", "Why", "Check", "Good", "Bad", "Eval", "Source")
DP_REQUIRED = ("Status", "Review by", "Question", "Options", "Default", "Why", "Applies to", "Source")
RULE_ALLOWED = RULE_REQUIRED + ("Replaced by", "Tool", "Exceptions") + CHANGES
DP_ALLOWED = DP_REQUIRED + ("Replaced by",)

NAME = r"[A-Z][A-Z0-9]*"
RULE_ID = re.compile(rf"{NAME}(?:-{NAME})+-[0-9]{{2,}}")
DP_ID = re.compile(rf"{NAME}(?:-{NAME})*-DP-[A-Z0-9]+(?:-[A-Z0-9]+)*")
ROLE = re.compile(r"[a-z]+(?: [a-z]+)*")
SKILL = re.compile(r"[a-z0-9]+(?:-[a-z0-9]+)*")
DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
PROSE = re.compile(r"[A-Za-z0-9(\[`].*")
FENCE = re.compile(r"`{3,}")
OPTION = re.compile(r"- `([a-z0-9-]+)`: \S.*")
CODE = re.compile(r"`([^`]*)`")  # a span in backticks: a decision point's Default names exactly one of its Options
BINDING = re.compile(rf"({DP_ID.pattern}): ([a-z0-9-]+)")  # Binds: the point's ID and the option it picks
HEADING = re.compile(r"### (\S+) · (\S.*)")
PART = re.compile(r"- \*\*([A-Za-z ]+):\*\*(?: (\S.*))?")
AREA_TITLE = re.compile(rf"# ({NAME}(?:-{NAME})*) · \S.*")
RETIRED_TITLE = re.compile(r"# Retired rules · \S.*")
RETIRED_FILE = re.compile(r"retired(?:-[a-z0-9]+)?\.md")
NOT_RULE_FILES = ("index.md", "README.md")


class RulebookError(Exception):
    """A line or value with no allowed shape, or a missing part."""


@dataclass
class Rule:
    id: str
    title: str
    file: str
    line: int
    parts: dict = field(default_factory=dict)  # part name -> list of lines, verbatim, 2-space indent removed

    @property
    def is_decision_point(self):
        return DP_ID.fullmatch(self.id) is not None

    @property
    def kind(self):
        return "decision point" if self.is_decision_point else self.text("Kind")

    @property
    def status(self):
        return self.text("Status")

    @property
    def area(self):
        """The area part of the ID (HW-RULE-03): TEST for CORE-TEST-03, DP for every decision point."""
        return "DP" if self.is_decision_point else self.id.split("-")[-2]

    @property
    def applies_to(self):
        return split_list(self.text("Applies to"))

    @property
    def changes(self):
        """The ID this rule overrides, binds or tightens, or None. For Binds, the decision point's ID."""
        value = next((self.text(name) for name in CHANGES if name in self.parts), None)
        return value.split(": ")[0] if value and "Binds" in self.parts else value

    @property
    def option(self):
        """The option a Binds rule picks, or None."""
        return self.text("Binds").split(": ")[1] if "Binds" in self.parts else None

    @property
    def options(self):
        """A decision point's option names, in order."""
        return [OPTION.fullmatch(line).group(1) for line in self.parts["Options"][1:] if OPTION.fullmatch(line)]

    @property
    def default(self):
        """A decision point's default option (check_rule proves it is one span in backticks naming an Option)."""
        return CODE.findall(self.text("Default"))[0]

    def text(self, part):
        """The part's lines joined with line breaks, exactly as the rulebook writes them."""
        return "\n".join(self.parts[part])


@dataclass
class Layer:
    folder: str
    rules: dict = field(default_factory=dict)  # ID -> Rule, active, inferred and retired alike


def split_list(value):
    """Split a comma-and-space list such as an Applies to value."""
    return value.split(", ") if value else []


def is_date(value):
    try:
        return date.fromisoformat(value) is not None
    except ValueError:
        return False


def fail(path, number, message):
    raise RulebookError(f"{path}:{number}: {message}")


def read_lines(path):
    """The file's lines. LF line endings and a final newline are required."""
    with open(path, encoding="utf-8", newline="") as handle:
        text = handle.read()
    if "\r" in text:
        fail(path, 1, "file has a carriage return; use LF line endings")
    if not text.endswith("\n"):
        fail(path, text.count("\n") + 1, "file does not end with a newline")
    return text[:-1].split("\n")


def read_layer(folder):
    """Read every rule file of one layer folder. The index and README are not read (HW-RULE-08)."""
    folder = Path(folder)
    if not folder.is_dir():
        fail(folder, 0, "not a layer folder")
    layer = Layer(str(folder))
    for path in sorted(p for p in folder.glob("*.md") if p.name not in NOT_RULE_FILES):
        for rule in read_rule_file(path):
            if rule.id in layer.rules:
                other = layer.rules[rule.id]
                fail(path, rule.line, f"{rule.id} already defined at {other.file}:{other.line}")
            layer.rules[rule.id] = rule
    return layer


def read_rule_file(path):
    """Read one area file or retired rules file and return its rules in file order."""
    path = Path(path)
    lines = read_lines(path)
    retired_file = RETIRED_FILE.fullmatch(path.name) is not None
    title = (RETIRED_TITLE if retired_file else AREA_TITLE).fullmatch(lines[0])
    if title is None:
        fail(path, 1, "first line is not the file title")
    prefix = None if retired_file else title.group(1)
    rules, rule, part, fence = [], None, None, ""
    for number, line in enumerate(lines[1:], start=2):
        heading = None if fence else HEADING.fullmatch(line)
        if heading:
            rule, part = start_rule(path, number, heading, prefix), None
            rules.append(rule)
        elif rule is None:
            if line and not PROSE.fullmatch(line):
                fail(path, number, f"line outside a rule is not prose: {line!r}")
        elif not fence and HEADING.fullmatch(line.lstrip()):
            fail(path, number, f"rule heading must not be indented: {line!r}")
        elif line.startswith("  ") and part is not None:
            text, run = line[2:].strip(), FENCE.match(line[2:].lstrip())
            if run and not fence:
                fence = run.group()  # a code block closes only on a line of at least as many backticks
            elif fence and text.startswith(fence) and text.strip("`") == "":
                fence = ""
            rule.parts[part].append(line[2:])
        elif line == "":
            if fence:
                rule.parts[part].append("")
            else:
                part = None
        elif fence:
            fail(path, number, "code block is not closed before the next part")
        else:
            part = add_part(path, number, rule, line)
    if fence:
        fail(path, len(lines), "code block is never closed")
    for index, rule in enumerate(rules):
        if rule.id in (other.id for other in rules[:index]):
            fail(path, rule.line, f"{rule.id} already defined in this file")
        check_rule(path, rule, retired_file)
    return rules


def start_rule(path, number, heading, prefix):
    rule_id, title = heading.groups()
    is_point = DP_ID.fullmatch(rule_id)
    is_rule = not is_point and RULE_ID.fullmatch(rule_id)
    if not (is_rule or is_point):
        fail(path, number, f"{rule_id!r} is not a rule or decision point ID")
    if prefix is not None:
        expected = re.fullmatch(rf"{prefix}-[0-9]{{2,}}", rule_id) if is_rule else (
            prefix.endswith("-DP") and rule_id.startswith(prefix + "-"))
        if not expected:
            fail(path, number, f"{rule_id} does not belong in a file titled {prefix}")
    return Rule(rule_id, title, str(path), number)


def add_part(path, number, rule, line):
    found = PART.fullmatch(line)
    if found is None:
        fail(path, number, f"line has no known shape inside {rule.id}: {line!r}")
    name = found.group(1)
    if name not in (DP_ALLOWED if rule.is_decision_point else RULE_ALLOWED):
        fail(path, number, f"part {name!r} is not allowed in {rule.id}")
    if name in rule.parts:
        fail(path, number, f"part {name!r} appears twice in {rule.id}")
    rule.parts[name] = [found.group(2) or ""]
    return name


def check_rule(path, rule, retired_file):
    required = DP_REQUIRED if rule.is_decision_point else RULE_REQUIRED
    missing = [name for name in required if name not in rule.parts]
    if missing:
        fail(path, rule.line, f"{rule.id} is missing {', '.join(missing)}")
    for name in rule.parts:
        check_value(path, rule, name)
    retired = rule.text("Status") == "retired"
    if retired != ("Replaced by" in rule.parts):
        fail(path, rule.line, f"{rule.id}: Replaced by is required exactly when the status is retired")
    if retired != retired_file:
        fail(path, rule.line, f"{rule.id}: retired rules live in retired files and only there (HW-RULE-07)")
    names = CODE.findall(rule.text("Default")) if rule.is_decision_point else [None]
    if len(names) != 1 or rule.is_decision_point and names[0] not in rule.options:
        fail(path, rule.line, f"{rule.id}: Default must name exactly one of its Options in backticks")
    if sum(name in rule.parts for name in CHANGES) > 1:
        fail(path, rule.line, f"{rule.id} names more than one of {', '.join(CHANGES)} (HW-RULE-05)")


def check_value(path, rule, name):
    """Each part's value must have its allowed shape. Text parts must not be empty."""
    value, lines = rule.text(name), rule.parts[name]
    if name in ("Options", "Source") and lines[0] == "":
        shape = OPTION if name == "Options" else re.compile(r"- \S.*")
        ok = len(lines) > 1 and all(shape.fullmatch(item) or item.startswith("  ") for item in lines[1:])
        ok = ok and not lines[1].startswith("  ")
    elif name == "Options":
        ok = False
    elif name == "Kind":
        ok = value in KINDS
    elif name == "Status":
        ok = value in STATUSES
    elif name == "Review by":
        ok = DATE.fullmatch(value) is not None and is_date(value)
    elif name == "Applies to":
        names = split_list(value)
        ok = bool(names) and len(set(names)) == len(names) and all(ROLE.fullmatch(n) for n in names)
    elif name == "Replaced by":
        ids = split_list(value)
        ok = value == "no replacement" or ids and all(RULE_ID.fullmatch(i) or DP_ID.fullmatch(i) for i in ids)
    elif name == "Binds":
        ok = BINDING.fullmatch(value) is not None
    elif name in CHANGES:
        ok = RULE_ID.fullmatch(value) is not None or DP_ID.fullmatch(value) is not None
    else:
        ok = value.strip() != ""
    if not ok:
        fail(path, rule.line, f"{rule.id}: {name} has no allowed value: {value!r}")


ROLES_COLUMNS = ("Role", "Group", "Purpose", "Produces", "Never does", "Model class", "Independent")
JOBS_COLUMNS = ("Job", "Roles", "Skills in order", "`rest` skill")


def read_roles(path):
    """Read v2/roles.md: the Roles table and the Jobs table, which may have no rows."""
    path = Path(path)
    lines = read_lines(path)
    roles = read_table(path, lines, "## Roles", ROLES_COLUMNS)
    jobs = read_table(path, lines, "## Jobs", JOBS_COLUMNS)
    classes = {f"{a} or {b}" for a in CLASSES for b in CLASSES if a != b} | set(CLASSES)
    for number, row in roles:
        ok = (ROLE.fullmatch(row["Role"]) and row["Role"] != EVERY_ROLE and ROLE.fullmatch(row["Group"])
              and row["Purpose"] and row["Produces"] and row["Model class"] in classes
              and row["Independent"] in ("yes", "no"))
        if not ok:
            fail(path, number, f"role row has a cell with no allowed value: {row}")
    for number, row in jobs:
        row["Roles"], row["Skills in order"] = split_list(row["Roles"]), split_list(row["Skills in order"])
        ok = (SKILL.fullmatch(row["Job"]) and row["Roles"] and row["Skills in order"]
              and all(ROLE.fullmatch(r) and r != EVERY_ROLE for r in row["Roles"])
              and all(SKILL.fullmatch(s) for s in row["Skills in order"])
              and row["`rest` skill"] in row["Skills in order"])
        if not ok:
            fail(path, number, f"job row has a cell with no allowed value: {row}")
    return {"roles": unique(path, roles, "Role"), "jobs": unique(path, jobs, "Job")}


def unique(path, rows, column):
    table = {}
    for number, row in rows:
        if row[column] in table:
            fail(path, number, f"{row[column]!r} is listed twice")
        table[row[column]] = row
    return table


def read_table(path, lines, heading, columns):
    """(line number, row) pairs under one heading. Prose may come before the table; after it, only blank lines."""
    if lines.count(heading) != 1:
        fail(path, 1, f"expected exactly one {heading!r} heading")
    start = lines.index(heading) + 1
    end = next((i for i in range(start, len(lines)) if lines[i].startswith("#")), len(lines))
    header = "| " + " | ".join(columns) + " |"
    if lines[start:end].count(header) != 1:
        fail(path, start, f"expected one table with the header {header} under {heading!r}")
    first = lines.index(header, start)
    rule_line = lines[first + 1] if first + 1 < end else ""
    if any(line.startswith("|") for line in lines[start:first]) or rule_line != "|" + "---|" * len(columns):
        fail(path, first + 1, f"table under {heading!r} is not a header, a rule line and rows")
    rows, number = [], first + 2
    while number < end and lines[number].startswith("|"):
        line = lines[number]
        cells = [cell.strip() for cell in line[1:-1].split("|")] if line.endswith("|") else []
        if len(cells) != len(columns):
            fail(path, number + 1, f"row needs {len(columns)} cells between '|' signs")
        rows.append((number + 1, dict(zip(columns, cells))))
        number += 1
    for index in range(number, end):
        if lines[index] != "":
            fail(path, index + 1, f"only blank lines may follow the table under {heading!r}")
    return rows


FRONTMATTER_KEYS = ("name", "description", "license", "compatibility")
TOP_LINE = re.compile(r"([a-z][a-z-]*): (\S.*)")
# Every value character is YAML-printable and not a tab or line break. A plain value starts with a letter, so it is
# never a number, date or special float, and is not a YAML 1.1 bool or null word, so every reader sees a string.
PRINTABLE = "[\x20-\x7e\xa0-\u2027\u202a-\ud7ff\ue000-\ufefe\uff00-\ufffd\U00010000-\U0010ffff]"
WORDS = r"(?:[yYnN]|[yY]es|YES|[nN]o|NO|[tT]rue|TRUE|[fF]alse|FALSE|[oO]n|ON|[oO]ff|OFF|[nN]ull|NULL)"
META_LINE = re.compile(rf"  (?!{WORDS}:)([a-z][a-z0-9-]*): (\S.*)")  # a key is a YAML string too
PLAIN = re.compile(rf"(?!{WORDS}$)[A-Za-z](?:(?!: | #){PRINTABLE})*(?<![ :])")
QUOTED = re.compile(rf"\"((?:(?![\"\\]){PRINTABLE})*)\"|'((?:(?!'){PRINTABLE})*)'")


def read_frontmatter(path):
    """The frontmatter of a SKILL.tmpl.md or SKILL.md: top-level strings and a `metadata` map of strings.

    Returns the data and the 0-based index of the first body line. A value is a plain string that starts with a
    letter (PLAIN) or a quoted string without escapes. Any other shape fails, so every host reads the same string.
    """
    path = Path(path)
    lines = read_lines(path)
    if lines[0] != "---" or "---" not in lines[1:]:
        fail(path, 1, "file does not start with a frontmatter block")
    end = lines.index("---", 1)
    data, target = {}, None
    for number in range(1, end):
        line = lines[number]
        meta = META_LINE.fullmatch(line)
        top = TOP_LINE.fullmatch(line)
        if line == "metadata:" and "metadata" not in data:
            target = data["metadata"] = {}
        elif meta and target is not None:
            store(path, number + 1, target, meta.groups())
        elif top and top.group(1) in FRONTMATTER_KEYS:
            target = None
            store(path, number + 1, data, top.groups())
        else:
            fail(path, number + 1, f"frontmatter line has no allowed shape: {line!r}")
    return data, end + 1


def store(path, number, target, pair):
    key, value = pair
    quoted = QUOTED.fullmatch(value)
    if key in target:
        fail(path, number, f"{key!r} appears twice")
    if quoted:
        value = quoted.group(1) if quoted.group(1) is not None else quoted.group(2)
    elif PLAIN.fullmatch(value) is None:
        fail(path, number, f"value of {key!r} has no allowed shape: quote it, without escapes")
    target[key] = value

changes.release/changelog-writer/scripts/runfile:
"""The files one run writes beside its rules: `rules.md`, and `rules-text-<skill>.<stack>.md` per release skill and
stack (doc 03).

Standard library only. `rules.md` holds no rule text: per stack (one per language) it lists the rules that apply,
the decision points, the waivers and the replaced rules, then the SHA-256 of every file read and every rules text
written, and the rules texts parked over the ceiling.

A rules text holds, for one skill and one stack (owner, 2026-11-13: one file per language), the rules from layers
2 to 6 that reach the skill's run and the CORE rules that reach it but the skill did not copy, in full; one line for
each change to a rule that reaches (what replaced it, what tightened it, its waiver); one line per decision point
that reaches, with its option and where that came from; and a read-back block that names its stack. What reaches is
reach.reach over every active rule of the stack, with the skill's copied IDs as cited, so a rule that changes a
copied CORE rule reaches too (reviews/release-design/size-final.md section 1). A rule that lost to a more specific
input appears only as its "replaced by" line, never in full.
"""

import hashlib
import os
from pathlib import Path

import copyform
import reach
from repoprofile import ResolveError

RUN = ".harness/runs/{run}"
RULES_MD = RUN + "/rules.md"
RULES_TEXT = RUN + "/rules-text-{skill}.{stack}.md"
MARKS = "### Changes to rules that reach this run"
POINTS = "### Decision points"


def cell(text):
    return str(text).replace("|", "\\|")


def row(*cells):
    return "| " + " | ".join(cell(c) for c in cells) + " |"


def relative(repo, path):
    return Path(os.path.relpath(Path(path).resolve(), Path(repo).resolve())).as_posix()


def sha(data):
    return hashlib.sha256(data).hexdigest()


def stack_md(inputs, done):
    """One stack's sections of rules.md."""
    applied = {w["rule"]: w for w in done.waivers if w not in inputs.expired}
    lines = ["", f"## Stack: {done.stack}", "", "### Rules", "", "| ID | Layer | Kind | Changes | Waiver |",
             "|---|---|---|---|---|"]
    for rule_id, (rule, layer, change) in done.rules.items():
        waiver = applied.get(rule_id)
        lines.append(row(rule_id, layer, rule.kind, change, f"waived until {waiver['until']}" if waiver else ""))
    lines += ["", "### Decision points", "", "| Point | Option | From |", "|---|---|---|"]
    lines += [row(point, option, source) for point, (option, source) in done.points.items()]
    lines += ["", "### Waivers", "", "| Rule | Reason | Until | Approved by | Status |", "|---|---|---|---|---|"]
    for waiver in done.waivers:
        status = ("expired" if waiver in inputs.expired else
                  f"replaced by {done.last(waiver['rule'])}" if waiver["rule"] in done.replaced else "applied")
        lines.append(row(waiver["rule"], waiver["reason"], waiver["until"], waiver["approved by"], status))
    lines += ["", "### Replaced", "", "| Rule | Replaced by |", "|---|---|"]
    return lines + [row(rule_id, by) for rule_id, by in done.replaced.items()]


def rules_md(repo, run, today, inputs, stacks_done, texts=None, parked=None):
    """The resolved standards file. texts maps each written rules text's path to its text; parked maps each parked
    (skill, stack) to (size, owner of its largest layer)."""
    lines = ["# Resolved standards", "", f"- **Run:** {run}", f"- **Date:** {today.isoformat()}",
             f"- **Release:** {inputs.version}"]
    for done in stacks_done:
        lines += stack_md(inputs, done)
    lines += ["", "## Files read", "", "| SHA-256 | File |", "|---|---|"]
    lines += [row(sha(Path(path).read_bytes()), relative(repo, path)) for path in inputs.files]
    lines += ["", "## Rules texts", "", "| SHA-256 | File |", "|---|---|"]
    lines += [row(sha(text.encode("utf-8")), relative(repo, path)) for path, text in (texts or {}).items()]
    lines += ["", "## Parked rules texts", "", "| Skill | Stack | Size | Limit | Owner of the largest layer |",
              "|---|---|---|---|---|"]
    lines += [row(skill, stack, size, inputs.limit, owner) for (skill, stack), (size, owner) in (parked or {}).items()]
    return "\n".join(lines) + "\n"


def write_once(path, text):
    """Write a run file once. If the run already has it, the new text must be the same bytes."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        with path.open("xb") as file:  # created here or not at all, so a second resolve never overwrites it
            file.write(text.encode("utf-8"))
    except FileExistsError:
        if path.read_bytes() != text.encode("utf-8"):
            raise ResolveError(f"{path} already exists and differs from this resolve: an input changed during "
                               "the run; start a new run") from None
    return path


def skills_of(manifest):
    """Each release skill as a reach.Skill, from the manifest; a job's `rest` skill keeps the areas `rest`."""
    return {name: reach.Skill(name, tuple(entry["roles"]), (reach.REST,) if entry["rest"] else tuple(entry["areas"]))
            for name, entry in manifest["skills"].items()}


def reached(name, inputs, rules, done):
    """What reaches a run of the skill over the active rules of one stack, in layer order, following what each rule
    replaces in this stack. The `rest` skill also takes, at run time, every area of the job's roles that no other
    skill of the job lists."""
    entry, skills = inputs.manifest["skills"][name], skills_of(inputs.manifest)
    areas = set(entry["areas"])
    if entry["rest"]:
        areas |= reach.areas_of(skills[name], reach.job(inputs.jobs, entry["job"]), skills, rules)
    replaces = {}
    for old, new in done.replaced.items():
        replaces.setdefault(new, []).append(old)
    return reach.reach(rules, entry["roles"], areas, entry["copied-ids"], replaces)


def tightened_by(rule, done):
    return [r.id for r, _, change in done.rules.values() if change == f"Tightens {rule.id}"]


def copy(rule, done):
    """The copy form of a rule written in full. An override carries its Why as the reason (doc 03), and a floor that
    a more specific floor tightens says so."""
    extra = copyform.part_lines(rule, "Why", "Reason for the override") if "Overrides" in rule.parts else []
    if tightened_by(rule, done):
        extra.append(f"- **Tightened by:** {', '.join(tightened_by(rule, done))}")
    return copyform.block(rule, copyform.RULE_PARTS, extra)


def stack_text(name, inputs, rules, done):
    """One stack's section of a rules text, and its full copies as (rule, layer prefix, text)."""
    copied = set(inputs.manifest["skills"][name]["copied-ids"])
    waived = {w["rule"]: w for w in done.waivers if w not in inputs.expired}
    marks, points, full = [], [], []
    for rule in reached(name, inputs, rules, done).rules:
        head = f"- {rule.id} · {rule.title}:"
        if rule.id in done.replaced:
            marks.append(f"{head} replaced by {done.replaced[rule.id]}")
        elif rule.is_decision_point:
            option, source = done.points[rule.id]
            points.append(f"{head} `{option}` (from {source})")
        else:
            if rule.id in waived:
                marks.append(f"{head} waived until {waived[rule.id]['until']}: {waived[rule.id]['reason']}")
            if rule.id not in copied:
                full.append((rule, done.rules[rule.id][1], copy(rule, done)))
            elif tightened_by(rule, done):
                marks.append(f"{head} tightened by {', '.join(tightened_by(rule, done))}")
    floors = [f for f in full if f[0].kind == "floor"]
    others = [f for f in full if f[0].kind != "floor"]
    lines = [f"## Stack: {done.stack}", "", MARKS, ""] + (marks or ["None."]) + ["", POINTS, ""] + (points or ["None."])
    for title, group in ((copyform.FLOORS, floors), (copyform.OTHERS, others)):
        lines += ["", title, ""] + ("\n\n".join(text for _, _, text in group) or "None.").split("\n")
    text = "\n".join(lines) + "\n\n" + copyform.read_back([rule for rule, _, _ in floors + others], done.stack)
    return text, full


def rules_text(name, inputs, rules, done):
    """One skill's rules text for one stack, and its full copies. rules are the active rules the stack holds."""
    text, full = stack_text(name, inputs, rules, done)
    return f"# Rules text: {name}\n\n- **Release:** {inputs.version}\n\n" + text, full


def largest_owner(full, inputs):
    """The owner of the layer whose full copies are largest in a rules text, and the sizes per layer and area."""
    sizes = {}
    for rule, layer, text in full:
        sizes[(layer, rule.area)] = sizes.get((layer, rule.area), 0) + reach.size(text)
    by_layer = {}
    for (layer, _), count in sizes.items():
        by_layer[layer] = by_layer.get(layer, 0) + count
    owners = {s.prefix: s.owner for s in inputs.sources}
    largest = max(sorted(by_layer), key=lambda layer: by_layer[layer], default=None)
    return owners.get(largest, "the application owner"), sizes
